import{isNode}from"../environment.js";let debugModule=null;export async function importDebug(){return debugModule||(debugModule=(await import("debug")).default),debugModule}export const debug=e=>isNode?async(...t)=>{captureLogs&&capturedLogs.push(e+t),(await importDebug())(e)(t)}:(...t)=>{const o=globalThis.__PUPPETEER_DEBUG;if(!o)return;("*"===o||(o.endsWith("*")?e.startsWith(o):e===o))&&console.log(`${e}:`,...t)};let capturedLogs=[],captureLogs=!1;export function setLogCapture(e){capturedLogs=[],captureLogs=e}export function getCapturedLogs(){return capturedLogs}